from datetime import datetime, timedelta
from base64 import b64encode
from functools import wraps
import logging
from urllib3.util.retry import MaxRetryError
from taf.internal.cloud.lcmaas.client.lcmaas.v1 import (AuthenticationsApi, LoginIn, ApiException)
from taf.cloud.lcmaas.exception import IncorrectLoginCredentials, HostConnectedFailed

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AUTHv1(object):
    def __init__(self, api_client):
        self.auth = AuthenticationsApi(api_client=api_client)

    def login(self, username, password):
        login_in = LoginIn(username=username,
                           password=b64encode(password.encode(encoding='utf-8')).decode())

        try:
            auth_session = self.auth.login_post(login_in=login_in)
        except ApiException as e:
            logger.error('LCMaaS username password validation failed')
            raise IncorrectLoginCredentials('Authentication failed. {}'.format(e))
        except MaxRetryError as e:
            logger.error('LCMaaS host can not be reached, max retries exceeded')
            raise HostConnectedFailed(e)

        return auth_session.jwt


class TokenProvider(object):

    @staticmethod
    def provide_access_token(func):
        @wraps(func)
        def wrapper(lcmaas_instance, *args, **kwargs):
            if lcmaas_instance.jwt_token_create_time + timedelta(hours=1) <= datetime.now():
                jwt_token = lcmaas_instance.auth.login(username=lcmaas_instance.conn_details.username,
                                                       password=lcmaas_instance.conn_details.password)

                lcmaas_instance.conf.access_token = jwt_token
            else:
                lcmaas_instance.conf.access_token = lcmaas_instance.jwt_token
            return func(lcmaas_instance, *args, **kwargs)

        return wrapper
